fn solve(x: i32) -> i32 {
    // Convert x to string to analyze its digits
    let x_str = x.to_string();
    let first_char = x_str.chars().next().unwrap();
    let d = first_char.to_digit(10).unwrap() as i32;
    let k = x_str.len() as i32;
    
    // Calculate the position in the sequence
    // Numbers before digit d: (d-1) * 4 numbers
    // Within digit d: we're at position k (1-based)
    let position = (d - 1) * 4 + k;
    
    // Calculate total button presses
    // For each position i from 1 to position:
    // - The digit is: ((i-1)/4) + 1 (integer division)
    // - The length is: ((i-1) % 4) + 1
    // But we can compute more efficiently:
    // Sum of lengths = sum_{i=1}^{position} (((i-1) % 4) + 1)
    
    let mut total = 0;
    for i in 1..=position {
        let length = ((i - 1) % 4) + 1;
        total += length;
    }
    
    total
}